    end=next((j for j in range(i+1,len(ls)) if re.search(r'HIGHLIGHTS|CRITICAL QUESTIONS|ABILITY ZONE|Power Points|^\d\.\d\s',ls[j],re.I)),len(ls))
    c['boxes'].append(dict(title=l.strip('!• '),page=p['id'],image=p['image'],text='\n'.join(ls[i+1:end])))
